def transform(grid):
    """Repeat the encoded one-dimensional color sequence as parallel bands."""
    h, w = len(grid), len(grid[0]) if grid else 0
    # Detect horizontal bands first; each band encodes one sequence position.
    rows = []
    for row in grid:
        vals = [v for v in row if v]
        if vals and len(set(vals)) == 1:
            rows.append(vals[0])
        else:
            rows.append(None)
    marked = [(i, v) for i, v in enumerate(rows) if v is not None]
    # If samples are sparse, infer the smallest period agreeing with every
    # observed band, and fill by the corresponding sampled phase.
    if marked:
        for period in range(1, h + 1):
            residues = {}
            ok = True
            for i, v in marked:
                r = i % period
                if r in residues and residues[r] != v:
                    ok = False
                    break
                residues[r] = v
            if ok and len(residues) >= 2:
                # Fill missing residues by nearest cyclic continuation; if the
                # sequence is fully observed, preserve it exactly.
                for r in range(period):
                    if r not in residues:
                        left = next((residues[(r-d) % period] for d in range(1, period+1) if (r-d) % period in residues), 0)
                        residues[r] = left
                return [[residues[i % period] for _ in range(w)] for i in range(h)]
    return [row[:] for row in grid]
